// Extended Applications & Characteristics for all 118 Chemical Elements (VI & EN)
// Format per Z: [viApps[], enApps[], viTrait, enTrait]

window.ELEMENT_DETAILS = {
  1: [['Nhiên liệu tên lửa & pin nhiên liệu hydro','Sản xuất amoniac (NH₃) và phân bón','Tinh chế dầu mỏ và hydro hóa dầu thực vật'],['Rocket propellant & hydrogen fuel cells','Ammonia (NH₃) & fertilizer synthesis','Petroleum refining & food hydrogenation'],'Chiếm khoảng 75% khối lượng vật chất thông thường của vũ trụ; không màu, không mùi và nhẹ nhất mọi nguyên tố.','Makes up ~75% of all normal baryonic mass in the universe; colorless, odorless, and the lightest element.'],
  2: [['Làm lạnh nam châm siêu dẫn trong máy chụp MRI','Khinh khí cầu, bóng thám không & khí nâng an toàn','Khí bảo vệ khi hàn hồ quang và tạo môi trường trơ sản xuất chip'],['Superconducting magnet cooling in MRI scanners','Airships, weather balloons & non-flammable lifting gas','Inert shielding gas for arc welding & chip fabrication'],'Có điểm sôi thấp nhất mọi nguyên tố (-268,93°C) và hầu như không tạo hợp chất hóa học bền ở điều kiện thường.','Has the lowest boiling point of any element (-268.93°C) and resists forming chemical bonds under normal conditions.'],
  3: [['Pin sạc lithium-ion cho điện thoại, laptop và xe điện','Gốm sứ và thủy tinh chịu sốc nhiệt cao','Hợp kim nhôm-liti siêu nhẹ ngành hàng không & thuốc ổn định khí sắc'],['Rechargeable lithium-ion batteries for EVs & electronics','Thermal-shock-resistant glass & ceramics','Ultralight aerospace Al-Li alloys & mood-stabilizing medicine'],'Kim loại rắn nhẹ nhất (0,534 g/cm³), mềm đến mức cắt được bằng dao và phản ứng nhanh với nước tạo khí H₂.','Lightest solid metal (0.534 g/cm³), soft enough to cut with a knife, reacting briskly with water to release H₂.'],
  4: [['Cửa sổ ống tia X nhờ độ xuyên thấu bức xạ cực cao','Gương siêu nhẹ trên kính viễn vọng không gian James Webb','Hợp kim đồng-beri không phát tia lửa cho lò xo và dụng cụ chống nổ'],['X-ray tube windows due to high radiation transparency','Lightweight mirrors on the James Webb Space Telescope','Non-sparking beryllium-copper alloys for springs & safety tools'],'Rất cứng, nhẹ và dẫn nhiệt xuất sắc, nhưng bụi và hợp chất beri có độc tính cao khi hít phải.','Remarkably stiff, light, and thermally conductive, though beryllium dust and compounds are toxic if inhaled.'],
  5: [['Thủy tinh borosilicat chịu nhiệt (Pyrex) và sợi thủy tinh cách nhiệt','Chất pha tạp loại p trong công nghệ vi mạch bán dẫn','Nam châm vĩnh cửu NdFeB và thanh kiểm soát neutron hạt nhân'],['Heat-resistant borosilicate glass (Pyrex) & fiberglass','p-type dopant in semiconductor microelectronics','NdFeB permanent magnets & nuclear neutron absorbers'],'Á kim cực cứng với nhiệt độ nóng chảy trên 2000°C, tạo nhiều liên kết cộng hóa trị giàu năng lượng.','Extremely hard metalloid melting above 2000°C, forming strong covalent networks and boron-rich compounds.'],
  6: [['Vật liệu siêu cứng (kim cương), điện cực & bút chì (than chì)','Sợi cacbon siêu bền cho máy bay, siêu xe và đồ thể thao','Lọc nước/khí (than hoạt tính) và nền tảng hóa học hữu cơ, polyme'],['Cutting tools & jewelry (diamond), electrodes & pencils (graphite)','High-strength carbon-fiber composites for aerospace & sports','Activated carbon filtration & backbone of organic chemistry'],'Khả năng tự liên kết mạch dài vô tận tạo ra hàng chục triệu hợp chất hữu cơ và các dạng thù hình kỳ diệu như graphene.','Unrivaled ability to form long chains and rings creates millions of organic compounds and allotropes like graphene.'],
  7: [['Sản xuất phân đạm (urê, nitrat) nuôi sống nông nghiệp toàn cầu','Nitơ lỏng (-196°C) bảo quản mẫu sinh học và cấp đông thực phẩm','Khí trơ bơm bao bì thực phẩm, lốp xe và bảo vệ linh kiện điện tử'],['Nitrogen fertilizers (urea, nitrates) supporting global agriculture','Liquid nitrogen (-196°C) for cryopreservation & rapid freezing','Inert flushing gas for food packaging, tires & electronics'],'Phân tử N₂ có liên kết ba rất bền nên khá trơ ở nhiệt độ thường, chiếm tới 78% thể tích khí quyển Trái Đất.','Its triple-bonded N₂ molecule is very unreactive at room temperature and comprises 78% of Earth’s atmosphere.'],
  8: [['Hỗ trợ hô hấp y tế, hàng không vũ trụ và lặn biển','Luyện thép bằng lò thổi oxi và hàn cắt kim loại nhiệt độ cao','Chất oxi hóa trong động cơ tên lửa và xử lý nước thải'],['Medical respiration, aviation & deep-sea breathing mixes','Basic oxygen steelmaking & oxy-acetylene welding/cutting','Liquid rocket oxidizer & wastewater treatment'],'Tính oxi hóa mạnh, chiếm gần 50% khối lượng vỏ Trái Đất (trong oxit, silicat) và tạo tầng ozon O₃ bảo vệ sinh quyển.','Strong oxidizer making up nearly half of Earth’s crust by mass and forming the UV-shielding ozone layer (O₃).'],
  9: [['Hợp chất florua chống sâu răng trong kem đánh răng','Nhựa chống dính PTFE (Teflon) và màng lọc chịu hóa chất','Làm giàu nhiên liệu hạt nhân (UF₆) và khắc mạch bán dẫn'],['Toothpaste fluorides for dental enamel protection','Non-stick PTFE (Teflon) coatings & chemical-resistant seals','Uranium enrichment (UF₆) & semiconductor plasma etching'],'Có độ âm điện cao nhất bảng tuần hoàn (3,98), phản ứng mãnh liệt với hầu hết nguyên tố kể cả một số khí hiếm nặng.','Highest electronegativity of any element (3.98), reacting vigorously with nearly every substance including heavy noble gases.'],
  10: [['Đèn ống neon quảng cáo phát ánh sáng đỏ cam đặc trưng','Laser Heli-Neon (He-Ne) trong đo đạc quang học và quét mã vạch','Môi chất làm lạnh nhiệt độ cực thấp (cryogenic) thay thế heli lỏng'],['Iconic orange-red glowing neon advertising tubes','Helium-Neon (He-Ne) lasers for optics & metrology','Cryogenic refrigerant with high cooling capacity per volume'],'Khí hiếm đơn nguyên tử cực kỳ trơ hóa học, phát quang rực rỡ khi phóng điện áp cao qua ống áp suất thấp.','Chemically inert monatomic noble gas producing intense reddish-orange light under high-voltage discharge.'],
  11: [['Muối ăn (NaCl), xút (NaOH) và baking soda (NaHCO₃) trong đời sống','Đèn hơi natri ánh sáng vàng chiếu sáng đường phố hiệu suất cao','Chất truyền nhiệt natri lỏng trong một số lò phản ứng hạt nhân nhanh'],['Table salt (NaCl), caustic soda (NaOH) & baking soda (NaHCO₃)','High-efficiency yellow sodium-vapor street lighting','Liquid-metal coolant in fast-breeder nuclear reactors'],'Kim loại kiềm mềm ánh bạc, nổi trên nước và phản ứng tỏa nhiệt mạnh tạo dung dịch kiềm cùng khí hydro.','Soft silvery alkali metal that floats on water and reacts exothermically to form alkaline solution and hydrogen.'],
  12: [['Hợp kim siêu nhẹ trong vỏ laptop, máy ảnh, khung xe và máy bay','Pháo sáng, pháo hoa nhờ ngọn lửa trắng chói mắt','Thuốc kháng axit dạ dày (Mg(OH)₂) và phân bón bổ sung diệp lục'],['Ultralight alloys for laptops, cameras, vehicles & aircraft','Flares and pyrotechnics due to blinding white combustion','Antacids (Mg(OH)₂) & essential plant chlorophyll nutrient'],'Kim loại kết cấu nhẹ nhất được dùng rộng rãi trong công nghiệp, có lớp màng oxit mỏng bảo vệ bề mặt.','Lightest widely used structural metal; naturally forms a thin protective oxide layer in air.'],
  13: [['Khung thân máy bay, ô tô, tàu cao tốc và kết cấu xây dựng','Bao bì lon đồ uống, giấy bạc thực phẩm và dây tải điện cao thế','Tản nhiệt máy tính, gương phản xạ và hợp kim hàng không'],['Aircraft fuselages, vehicles, trains & architectural frames','Beverage cans, food foil & overhead power transmission lines','Electronic heatsinks, reflectors & lightweight alloys'],'Chỉ nặng khoảng 1/3 thép nhưng bền chắc, dẫn điện tốt, chống ăn mòn tự nhiên và tái chế vô hạn gần như không mất chất.','About one-third the density of steel yet strong, conductive, corrosion-resistant, and endlessly recyclable.'],
  14: [['Tấm wafer silic siêu tinh khiết chế tạo CPU, GPU và bộ nhớ','Tế bào quang điện trong hệ thống pin năng lượng mặt trời','Thủy tinh, xi măng, gốm sứ và cao su silicone chịu nhiệt'],['Ultrapure silicon wafers for CPUs, GPUs & memory chips','Photovoltaic cells powering solar energy panels','Glass, cement, ceramics & heat-resistant silicone polymers'],'Nguyên tố phổ biến thứ hai trong vỏ Trái Đất (~28%), có cấu trúc tinh thể kim cương lý tưởng để kiểm soát dòng điện bán dẫn.','Second most abundant element in Earth’s crust (~28%), with a diamond-cubic crystal ideal for semiconductor switching.'],
  15: [['Phân lân (photphat) tăng năng suất cây trồng trên toàn cầu','Vỏ hộp diêm an toàn (photpho đỏ) và chất chống cháy','Hợp kim đồng photpho, đèn LED và thành phần sinh học ADN/ATP'],['Phosphate fertilizers essential to global food production','Safety match striker strips (red phosphorus) & flame retardants','Phosphor bronze alloys, LEDs & biological DNA/ATP backbone'],'Tồn tại ở nhiều dạng thù hình rất khác biệt: photpho trắng phát sáng trong tối và tự bốc cháy, trong khi photpho đỏ bền hơn nhiều.','Exists in striking allotropes: waxy white phosphorus glows and self-ignites in air, whereas red phosphorus is stable.'],
  16: [['Sản xuất axit sunfuric (H₂SO₄) — hóa chất công nghiệp số 1 thế giới','Lưu hóa cao su làm lốp xe bền đàn hồi hơn','Thuốc trừ nấm nông nghiệp, thuốc súng đen và pin Li-S thế hệ mới'],['Sulfuric acid (H₂SO₄) — the world’s top industrial chemical','Rubber vulcanization for durable automotive tires','Agricultural fungicides, black powder & next-gen Li-S batteries'],'Tinh thể vàng chanh đặc trưng dễ nóng chảy, xuất hiện tự nhiên dày đặc quanh các suối nước nóng và miệng núi lửa.','Distinctive lemon-yellow crystalline nonmetal abundant near volcanic vents and geothermal springs.'],
  17: [['Khử trùng nước máy sinh hoạt và nước hồ bơi trên toàn cầu','Sản xuất nhựa PVC, dung môi công nghiệp và chất tẩy trắng','Tổng hợp dược phẩm (hơn 85% thuốc cần clo trong quy trình sản xuất)'],['Disinfection of municipal drinking water & swimming pools','Production of PVC plastics, solvents & household bleach','Pharmaceutical synthesis (used in over 85% of medicines)'],'Khí màu vàng lục nặng hơn không khí, mùi hắc mạnh và có tính oxi hóa, diệt khuẩn rất cao.','Dense yellow-green gas with a sharp odor and powerful oxidizing and germicidal activity.'],
  18: [['Khí bảo vệ chống oxi hóa trong hàn TIG/MIG kim loại','Bơm bên trong kính hai lớp cách nhiệt và bóng đèn sợi đốt','Tạo môi trường trơ luyện kim tinh khiết (titan, silic bán dẫn)'],['Inert shielding gas for TIG and MIG metal welding','Thermal insulation fill inside double-glazed windows & bulbs','Oxygen-free atmosphere for refining titanium & silicon crystals'],'Chiếm gần 1% khí quyển Trái Đất, rẻ và trơ tuyệt đối nên là lựa chọn khí bảo vệ phổ biến nhất công nghiệp.','Comprises nearly 1% of Earth’s atmosphere; inexpensive and completely inert, making it industry’s go-to shielding gas.'],
  19: [['Phân bón kali (KCl, K₂SO₄) thiết yếu cho nông nghiệp','Xà phòng lỏng (KOH), thủy tinh quang học và muối thay thế ít natri','Chất điện giải thiết yếu duy trì nhịp tim và hệ thần kinh con người'],['Potash fertilizers (KCl, K₂SO₄) vital for agriculture','Liquid soaps (KOH), specialty glass & low-sodium salt','Essential electrolyte regulating heartbeat & nerve impulses'],'Mềm như sáp, cháy với ngọn lửa màu tím hoa cà đặc trưng và phản ứng còn mãnh liệt hơn cả natri khi gặp nước.','Waxy soft metal burning with a lilac flame and reacting even more vigorously with water than sodium.'],
  20: [['Sản xuất xi măng, vữa xây dựng, thạch cao và vôi công nghiệp','Khử oxi và khử tạp chất trong luyện thép, hợp kim nhôm','Thành phần khoáng thiết yếu của xương, răng và sữa dinh dưỡng'],['Cement, mortar, gypsum plaster & industrial lime','Deoxidizer and desulfurizer in steel & alloy refining','Vital structural mineral in bones, teeth & nutrition'],'Kim loại phổ biến thứ 5 trong vỏ Trái Đất, hiếm khi tồn tại dạng tự do mà chủ yếu trong đá vôi (CaCO₃) và thạch cao.','Fifth most abundant element in Earth’s crust, found widely in limestone, marble, and chalk rather than free metal.'],
  21: [['Hợp kim nhôm-scandi siêu bền nhẹ cho khung xe đạp, gậy bóng chày và máy bay','Đèn halogen kim loại chiếu sáng sân vận động mô phỏng ánh sáng mặt trời','Tế bào nhiên liệu oxit rắn (SOFC) hiệu suất cao'],['High-strength Al-Sc alloys for aircraft, bikes & sports gear','Stadium metal-halide lamps mimicking natural sunlight','Solid oxide fuel cell (SOFC) electrolytes'],'Kim loại chuyển tiếp nhẹ màu trắng bạc, giúp tinh chỉnh cấu trúc hạt kim loại và chống nứt mối hàn cực tốt.','Lightweight silvery transition metal that refines alloy grain structure and greatly improves weld durability.'],
  22: [['Thân vỏ máy bay chiến đấu, động cơ phản lực và tàu vũ trụ','Khớp nhân tạo, trụ răng implant và nẹp vít phẫu thuật y tế','Bột màu trắng TiO₂ siêu bền trong sơn, nhựa và kem chống nắng'],['Jet engines, spacecraft & high-performance airframes','Biocompatible joint replacements, dental implants & surgical pins','Brilliant white TiO₂ pigment in paints, plastics & sunscreens'],'Bền ngang thép nhưng nhẹ hơn tới 45%, hoàn toàn không bị nước biển ăn mòn và an toàn tuyệt đối trong cơ thể người.','As strong as steel yet 45% lighter, impervious to seawater corrosion, and fully biocompatible with human tissue.'],
  23: [['Thép hợp kim vanadi chịu tải cho trục xe, bánh răng và công cụ cắt','Pin dòng chảy vanadi (VRFB) lưu trữ điện quy mô lớn cho lưới điện','Chất xúc tác V₂O₅ trong sản xuất axit sunfuric công nghiệp'],['High-strength vanadium steel for axles, gears & hand tools','Grid-scale vanadium redox flow batteries (VRFB)','V₂O₅ catalyst in industrial sulfuric acid production'],'Nổi tiếng trong hóa học nhờ tạo dung dịch nhiều màu sắc rực rỡ (tím, xanh lục, xanh lam, vàng) tương ứng 4 mức oxi hóa.','Celebrated in chemistry for forming vivid violet, green, blue, and yellow solutions across four oxidation states.'],
  24: [['Thành phần cốt lõi (≥10,5%) tạo nên thép không gỉ (inox)','Lớp mạ crom bóng gương chống trầy xước và chống gỉ cho chi tiết máy','Tạo màu đỏ cho hồng ngọc (ruby) và màu xanh lục cho ngọc lục bảo'],['Essential ingredient (≥10.5%) in stainless steel','Mirror-bright wear- and corrosion-resistant chrome plating','Coloring impurity in rubies (red) and emeralds (green)'],'Kim loại rất cứng có ánh bạc xanh đặc trưng; tên gọi "Chroma" bắt nguồn từ sự đa sắc của các hợp chất crom.','Very hard bluish-silver metal whose name comes from Greek "chroma" for the vivid colors of its compounds.'],
  25: [['Khử oxi, khử lưu huỳnh và tăng độ cứng chống va đập cho hầu hết các loại thép','Cực dương MnO₂ trong pin kiềm và pin kẽm-cacbon dân dụng','Hợp kim nhôm vỏ lon đồ uống chống ăn mòn'],['Essential steelmaking additive for toughness & wear resistance','MnO₂ cathode material in alkaline & dry-cell batteries','Corrosion-resistant aluminum alloys for beverage cans'],'Gần 90% sản lượng mangan toàn cầu phục vụ ngành luyện thép — không có kim loại thay thế hoàn toàn hiệu quả hơn.','Nearly 90% of global manganese output goes into steelmaking, where it has no fully satisfactory substitute.'],
  26: [['Vật liệu nền tảng tạo nên thép, gang cho cầu đường, tòa nhà và máy móc','Lõi nam châm điện, máy biến áp và động cơ điện công nghiệp','Hồng cầu (hemoglobin) vận chuyển oxi trong máu động vật có xương sống'],['Steel & cast iron for bridges, buildings, ships & machinery','Electromagnet cores, transformers & electric motors','Oxygen transport inside hemoglobin of red blood cells'],'Chiếm tỷ trọng lớn nhất toàn hành tinh Trái Đất (lõi sắt-niken) và có tính sắt từ mạnh dễ từ hóa.','Earth’s most abundant element by total planetary mass (forming the core) and a classic ferromagnetic metal.'],
  27: [['Vật liệu cực dương mật độ năng lượng cao trong pin sạc lithium-ion','Siêu hợp kim chịu nhiệt cho cánh tuabin động cơ phản lực','Bột màu xanh coban bền vững cho gốm sứ, thủy tinh và hội họa'],['High-energy-density cathodes in lithium-ion batteries','Heat-resistant superalloys for jet turbine blades','Deep cobalt-blue pigments for ceramics, glass & fine art'],'Giữ được từ tính ở nhiệt độ cực cao (điểm Curie ~1115°C) và là nguyên tử trung tâm của vitamin B12.','Retains ferromagnetism up to 1115°C and forms the essential active center of vitamin B12.'],
  28: [['Sản xuất thép không gỉ austenit và siêu hợp kim chống ăn mòn biển','Pin sạc NiMH, pin xe điện giàu niken (NMC/NCA) và tiền xu','Chất xúc tác hydro hóa công nghiệp và lớp mạ chống oxi hóa'],['Austenitic stainless steel & marine corrosion-resistant alloys','NiMH & high-nickel EV batteries (NMC/NCA) plus coinage','Hydrogenation catalysts & protective electroplating'],'Dẻo, bóng bạc ánh vàng nhẹ, chống oxi hóa xuất sắc kể cả trong môi trường kiềm và nhiệt độ cao.','Ductile, silvery metal with a faint golden sheen that resists oxidation even in hot alkaline environments.'],
  29: [['Dây dẫn điện, cuộn dây motor, máy biến áp và mạch in PCB','Ống dẫn nước, bộ trao đổi nhiệt và tản nhiệt CPU/GPU','Hợp kim đồng thau (Cu-Zn), đồng thanh (Cu-Sn) và bề mặt kháng khuẩn'],['Electrical wiring, motor windings, transformers & PCBs','Plumbing pipes, heat exchangers & CPU/GPU thermal blocks','Brass (Cu-Zn), bronze (Cu-Sn) & antimicrobial touch surfaces'],'Một trong hai kim loại duy nhất không có màu bạc tự nhiên (cùng với vàng), đứng thứ 2 toàn bảng về độ dẫn điện sau bạc.','One of only two non-silvery pure metals (alongside gold), ranking second only to silver in electrical conductivity.'],
  30: [['Mạ kẽm nhúng nóng bảo vệ kết cấu thép khỏi rỉ sét hàng chục năm','Hợp kim đồng thau cho nhạc cụ, van khóa và linh kiện đúc áp lực','Kem chống nắng vật lý (ZnO), pin kẽm-không khí và vi chất miễn dịch'],['Hot-dip galvanizing protecting steel structures for decades','Brass alloys for instruments, valves & precision die-castings','Mineral sunscreens (ZnO), zinc-air batteries & immune nutrition'],'Bảo vệ thép theo cơ chế "anot hy sinh" — kẽm tự oxi hóa trước để giữ lớp thép bên trong nguyên vẹn.','Protects steel sacrificially by corroding first, shielding underlying iron even when the coating is scratched.'],
  31: [['Chip bán dẫn hiệu suất cao GaN (sạc nhanh, 5G) và GaAs (radar, vệ tinh)','Đèn LED phát sáng xanh dương, trắng và diode laser đầu đọc đĩa','Nhiệt kế không độc thay thế thủy ngân (hợp kim Galinstan)'],['High-power GaN (fast chargers, 5G) & GaAs (radar) chips','Blue/white LEDs and semiconductor laser diodes','Non-toxic mercury-free thermometers (Galinstan alloy)'],'Nóng chảy ở 29,76°C (tan ngay trên lòng bàn tay) nhưng sôi ở tận 2204°C — khoảng nhiệt độ thể lỏng rộng hàng đầu tự nhiên.','Melts at 29.76°C (in your palm) yet boils at 2204°C—giving one of the widest liquid temperature ranges of any metal.'],
  32: [['Lõi sợi cáp quang học viễn thông tăng chiết suất truyền dẫn','Thấu kính và cửa sổ camera nhiệt hồng ngoại nhìn đêm','Pin mặt trời không gian đa nối hiệu suất siêu cao và bán dẫn SiGe'],['High-index core dopant in fiber-optic communication cables','Lenses and windows for thermal imaging infrared cameras','High-efficiency space solar cells & SiGe high-speed chips'],'Á kim bán dẫn giòn ánh xám bạc, có tính trong suốt với bức xạ hồng ngoại và giãn nở nhẹ khi đông đặc giống nước.','Brittle silvery metalloid transparent to infrared light that, like water, expands slightly upon freezing.'],
  33: [['Chất bán dẫn hợp chất GaAs trong chip điện thoại, Wi-Fi và laser','Pha lượng nhỏ vào lưới chì giúp tăng độ cứng ắc quy ô tô','Nghiên cứu dược phẩm điều trị đặc hiệu một số thể bệnh bạch cầu'],['Compound semiconductor GaAs for RF chips, Wi-Fi & lasers','Hardening additive in lead-acid automotive battery grids','Targeted medical therapy for specific forms of leukemia'],'Á kim thăng hoa trực tiếp từ rắn sang hơi ở áp suất thường (614°C); các hợp chất vô cơ có độc tính rất cao.','Metalloid that sublimes directly from solid to gas at atmospheric pressure (614°C); inorganic compounds are highly toxic.'],
  34: [['Tế bào quang điện màng mỏng CIGS và trống cảm quang máy in/photocopy','Khử màu xanh sắt hoặc tạo sắc đỏ ruby rực rỡ cho thủy tinh','Vi chất dinh dưỡng chống oxi hóa và dầu gội trị gàu (SeS₂)'],['Thin-film CIGS solar cells & photocopier photoconductors','Decolorizing glass or creating deep ruby-red architectural glass','Antioxidant trace nutrient & anti-dandruff shampoos (SeS₂)'],'Có hiệu ứng quang dẫn mạnh: độ dẫn điện tăng vọt hàng trăm lần khi có ánh sáng chiếu vào.','Exhibits strong photoconductivity, increasing electrical conductivity dramatically when illuminated.'],
  35: [['Hợp chất chống cháy trong vỏ nhựa thiết bị điện tử và dệt may','Dung dịch khoan dầu khí mật độ cao và xử lý diệt khuẩn nước','Tổng hợp dược phẩm, thuốc nhuộm và phim ảnh bạc bromua truyền thống'],['Flame retardants in electronics casings & textiles','High-density oil-drilling brines & water sanitation','Pharmaceutical intermediates, dyes & silver bromide photography'],'Phi kim duy nhất tồn tại ở trạng thái lỏng tại 25°C, màu nâu đỏ sẫm, nặng hơn nước hơn 3 lần và bốc hơi cay mạnh.','The only nonmetal liquid at room temperature—a dense dark reddish-brown fluid that readily gives off acrid vapor.'],
  36: [['Đèn flash nhiếp ảnh tốc độ cao và đèn chiếu đường băng sân bay','Laser excimer KrF trong quang khắc sản xuất chip bán dẫn','Bơm kính cách âm, cách nhiệt cao cấp tiết kiệm năng lượng'],['High-speed photography flashes & airport runway strobes','KrF excimer lasers for semiconductor chip lithography','Premium thermally insulating multi-pane window gas fill'],'Khí hiếm nặng phát sáng trắng xanh rất sắc nét khi phóng điện; từng được dùng để định nghĩa chuẩn 1 mét quốc tế (1960–1983).','Heavy noble gas glowing bright whitish-blue in discharge tubes; defined the international meter from 1960 to 1983.'],
  37: [['Đồng hồ nguyên tử rubidi nhỏ gọn trên vệ tinh GPS và trạm viễn thông','Thí nghiệm ngưng tụ Bose-Einstein trong vật lý lượng tử lạnh sâu','Tế bào quang điện và pháo hoa tạo ánh sáng tím thẫm'],['Compact rubidium atomic clocks in GPS & telecom networks','Bose-Einstein condensate experiments in quantum physics','Photocells & deep purple pyrotechnic effects'],'Kim loại kiềm mềm nóng chảy chỉ ở 39,3°C, tự bốc cháy trong không khí và phản ứng nổ với nước.','Soft alkali metal melting at just 39.3°C, igniting spontaneously in air and reacting explosively with water.'],
  38: [['Pháo hoa và pháo sáng cứu hộ tạo sắc đỏ thẫm rực rỡ nhất','Đồng hồ nguyên tử mạng quang học stronti chính xác bậc nhất thế giới','Nam châm gốm ferit trong loa, động cơ nhỏ và sơn phát quang SrAl₂O₄'],['Brilliant crimson fireworks & emergency maritime flares','World’s most precise strontium optical lattice atomic clocks','Ferrite ceramic magnets & long-glowing SrAl₂O₄ phosphors'],'Kim loại kiềm thổ mềm ánh bạc nhanh chóng chuyển sang màu vàng khi tiếp xúc không khí do lớp oxit bề mặt.','Soft silvery alkaline earth metal that rapidly turns yellowish in air as a thin oxide film forms.'],
  39: [['Tinh thể laser YAG (Nd:YAG) cắt kim loại và phẫu thuật mắt','Bột phát quang chuyển ánh sáng xanh thành trắng trong đèn LED','Chất siêu dẫn nhiệt độ cao YBCO và gốm zirconia ổn định (YSZ)'],['Nd:YAG lasers for metal cutting & ophthalmic surgery','Phosphor coatings converting blue LEDs into crisp white light','High-temperature YBCO superconductors & stabilized zirconia'],'Thường xếp chung nhóm đất hiếm nhờ tính chất hóa học rất giống các nguyên tố họ Lantan dù nằm ở chu kì 5.','Grouped with rare-earth elements due to nearly identical chemical behavior to lanthanides despite sitting in period 5.'],
  40: [['Vỏ thanh nhiên liệu lò phản ứng hạt nhân nhờ hấp thụ neutron cực thấp','Gốm răng sứ zirconia siêu cứng thẩm mỹ và dao gốm sắc bén','Đá trang sức cubic zirconia (CZ) tán sắc gần giống kim cương'],['Nuclear fuel rod cladding thanks to minimal neutron absorption','Ultra-tough zirconia dental crowns & ceramic chef knives','Diamond-like cubic zirconia (CZ) gemstones & foundry bricks'],'Chống ăn mòn gần như hoàn hảo trước axit, kiềm và nước biển nhờ lớp màng oxit tự hồi phục.','Exceptionally resistant to acids, alkalis, and seawater thanks to a self-healing passive oxide skin.'],
  41: [['Cuộn dây nam châm siêu dẫn NbTi/Nb₃Sn trong máy MRI và máy gia tốc LHC','Thép hợp kim HSLA cường độ cao cho cầu treo, đường ống dầu khí','Động cơ tên lửa chịu nhiệt và trang sức không gây dị ứng'],['Superconducting NbTi/Nb₃Sn magnets in MRI scanners & the LHC','High-strength low-alloy (HSLA) steels for pipelines & bridges','Rocket nozzle superalloys & hypoallergenic anodized jewelry'],'Có nhiệt độ chuyển pha siêu dẫn cao nhất trong các kim loại nguyên chất (9,2 K) và dễ tạo màng oxit đổi màu cầu vồng khi anot hóa.','Highest superconducting transition temperature among pure metals (9.2 K) and anodizes into vivid iridescent colors.'],
  42: [['Tăng độ bền kéo và chịu nhiệt cho thép công cụ, thép không gỉ 316','Chất bôi trơn rắn MoS₂ chịu áp suất cao trong cơ khí hàng không','Chất xúc tác khử lưu huỳnh dầu mỏ và vi lượng cố định đạm thực vật'],['High-temperature strength additive in 316 stainless & tool steels','Solid lubricant MoS₂ for extreme-pressure aerospace bearings','Petroleum hydrodesulfurization catalysts & plant enzymes'],'Sở hữu nhiệt độ nóng chảy cao thứ 6 trong mọi nguyên tố (2623°C) với hệ số giãn nở nhiệt cực thấp.','Has the 6th highest melting point of all elements (2623°C) paired with minimal thermal expansion.'],
  43: [['Đồng vị Tc-99m phục vụ hơn 80% ca xạ hình chẩn đoán y học hạt nhân','Chất ức chế ăn mòn thép hiệu quả cực cao (muối pertechnetat)','Hiệu chuẩn thiết bị đo bức xạ beta trong phòng thí nghiệm'],['Isotope Tc-99m powering >80% of nuclear medicine imaging scans','Ultra-effective steel corrosion inhibitor (pertechnetate salts)','Beta-radiation detector calibration in scientific labs'],'Nguyên tố nhẹ nhất không có bất kỳ đồng vị bền nào — hoàn toàn phóng xạ và là nguyên tố đầu tiên được con người tổng hợp nhân tạo.','Lightest element with no stable isotopes—entirely radioactive and the first element ever synthesized artificially.'],
  44: [['Xúc tác phản ứng hóa học hữu cơ (đoạt giải Nobel Hóa học 2005)','Lớp phủ siêu bền chống mài mòn cho tiếp điểm điện và đĩa cứng','Hợp kim làm cứng platin và paladi trong trang sức, linh kiện'],['High-efficiency organic catalysts (2005 Nobel Prize in Chemistry)','Wear-resistant coatings for electrical contacts & hard drives','Hardening alloying agent for platinum & palladium'],'Kim loại quý nhóm platin rất cứng, không bị xỉn màu ở nhiệt độ phòng và trơ với hầu hết axit đơn lẻ.','Hard platinum-group metal that never tarnishes at room temperature and resists almost all single acids.'],
  45: [['Bộ chuyển đổi xúc tác 3 chiều khử khí độc NOx từ động cơ ô tô','Mạ vàng trắng và bạc giúp tạo độ sáng bóng gương và chống xỉn màu','Cặp nhiệt điện đo nhiệt độ siêu cao và gương phản xạ quang học'],['Three-way automotive catalytic converters reducing toxic NOx','Bright, tarnish-proof plating on white gold & fine silver','High-temperature thermocouples & optical searchlight mirrors'],'Nằm trong nhóm kim loại quý hiếm và đắt giá nhất thế giới, phản xạ tới ~80% ánh sáng khả kiến và chống ăn mòn tuyệt đối.','Among the rarest and costliest precious metals; reflects ~80% of visible light and resists corrosion completely.'],
  46: [['Bộ chuyển đổi xúc tác khí thải xe hơi (đặc biệt động cơ xăng)','Màng lọc tạo khí hydro siêu tinh khiết cho công nghệ pin nhiên liệu','Tụ điện gốm MLCC, trang sức vàng trắng và hợp kim nha khoa'],['Gasoline-engine automotive catalytic converters','Hydrogen purification membranes for fuel-cell technology','Multilayer ceramic capacitors, white gold & dental alloys'],'Có khả năng hấp thụ khí hydro giống như "miếng bọt biển kim loại" — chứa được lượng H₂ gấp 900 lần thể tích của chính nó.','Acts like a metallic sponge for hydrogen, absorbing up to 900 times its own volume of H₂ gas.'],
  47: [['Tiếp điểm điện tử, bảng mạch và keo dẫn điện trên pin mặt trời','Gương phản xạ quang học, đồ trang sức và tài sản tích trữ','Vật liệu kháng khuẩn trong băng gạc y tế và lọc nước tinh khiết'],['Electronic contacts, switches & solar-panel conductive pastes','High-reflectivity mirrors, fine jewelry & bullion','Antimicrobial wound dressings & water purification systems'],'Đứng số 1 toàn bảng tuần hoàn về cả độ dẫn điện, độ dẫn nhiệt lẫn khả năng phản xạ ánh sáng khả kiến.','Ranks #1 across the entire periodic table in electrical conductivity, thermal conductivity, and visible reflectivity.'],
  48: [['Pin mặt trời màng mỏng CdTe chi phí thấp hiệu suất cao','Chấm lượng tử (quantum dots) tạo dải màu siêu rộng trên TV QLED','Thanh điều khiển hấp thụ neutron trong lò phản ứng hạt nhân'],['Cost-effective thin-film CdTe solar modules','Quantum dots delivering vivid color gamuts in QLED displays','Neutron-absorbing control rods in nuclear reactors'],'Kim loại mềm dễ dát mỏng màu trắng ánh lam; hiện bị hạn chế trong sản phẩm tiêu dùng do tính độc tích lũy sinh học.','Soft bluish-white metal now restricted in consumer products like NiCd batteries due to cumulative toxicity.'],
  49: [['Lớp phủ dẫn điện trong suốt ITO trên màn hình cảm ứng điện thoại, TV','Hợp kim hàn nhiệt độ thấp và miếng tản nhiệt tiếp xúc CPU','Bán dẫn InP, InGaN cho đèn LED xanh và truyền thông quang tốc độ cao'],['Transparent conductive ITO coatings on touchscreens & displays','Low-melting solders & cryogenic thermal interface seals','InP & InGaN semiconductors for blue LEDs & fiber-optic lasers'],'Mềm đến mức có thể nhai hoặc khắc dấu bằng móng tay, và phát ra tiếng "rít" đặc trưng khi bẻ thanh kim loại.','So soft it can be scratched with a fingernail, emitting a distinct crackling "tin cry" when bent.'],
  50: [['Hợp kim hàn mạch điện tử không chì (Sn-Ag-Cu) an toàn môi trường','Tráng lớp chống ăn mòn bên trong vỏ hộp thực phẩm (sắt tây)','Hợp kim đồng thanh (bronze), thủy tinh nổi (float glass) và ống đàn organ'],['Lead-free Sn-Ag-Cu electronics solder','Corrosion-resistant lining inside steel food cans (tinplate)','Bronze alloys, float-glass production beds & organ pipes'],'Không độc, dễ đúc; dưới 13,2°C thiếc trắng có thể biến đổi chậm thành bột thiếc xám ("bệnh dịch thiếc").','Non-toxic and easily cast; below 13.2°C silvery beta-tin can slowly crumble into powdery gray alpha-tin ("tin pest").'],
  51: [['Chất hiệp đồng chống cháy (Sb₂O₃) trong vải, nhựa và vỏ dây cáp','Tăng độ cứng cho bản cực chì trong ắc quy ô tô và đạn thể thao','Cảm biến hồng ngoại InSb và hợp kim chữ in không co ngót'],['Sb₂O₃ flame-retardant synergist in textiles, plastics & cables','Hardening agent in lead-acid car battery plates','InSb infrared detectors & dimensionally stable type metal'],'Á kim ánh bạc có cấu trúc tinh thể vảy giòn, giãn nở nhẹ khi đông đặc nên rất lý tưởng để đúc chi tiết sắc nét.','Lustrous flaky brittle metalloid that expands slightly on freezing, ideal for sharp precision castings.'],
  52: [['Pin mặt trời màng mỏng CdTe — công nghệ quang điện lớn thứ hai thế giới','Mô-đun nhiệt điện Bi₂Te₃ làm lạnh bán dẫn và thu hồi nhiệt thải','Tăng khả năng gia công tiện cho thép và đồng hợp kim'],['CdTe thin-film solar panels — second-largest solar technology','Bi₂Te₃ thermoelectric coolers & waste-heat generators','Machinability enhancer in free-cutting steels & copper'],'Hiếm trong vỏ Trái Đất ngang ngửa platin nhưng lại khá phổ biến trong vũ trụ; có tính bán dẫn hướng tinh thể rõ rệt.','As scarce as platinum in Earth’s crust yet relatively abundant in the cosmos; shows strong semiconductor behavior.'],
  53: [['Muối iot phòng ngừa bướu cổ và hỗ trợ tổng hợp hormone tuyến giáp','Dung dịch sát trùng povidone-iodine trong sơ cứu và phẫu thuật','Chất cản quang X-quang, đèn halogen và phân cực màn hình LCD'],['Iodized salt preventing thyroid disorders worldwide','Povidone-iodine antiseptic solutions in surgery & first aid','Medical X-ray contrast media, halogen lamps & LCD polarizers'],'Tinh thể rắn màu tím đen ánh kim, khi đun nhẹ lập tức thăng hoa thành đám hơi màu tím rực rỡ rất đặc trưng.','Lustrous violet-black crystalline solid that sublimes gently into a vivid magenta-violet vapor.'],
  54: [['Động cơ đẩy ion xenon vận hành tàu vũ trụ và vệ tinh (Starlink, Dawn)','Đèn hồ quang xenon máy chiếu rạp phim và đèn pha ô tô cường độ cao','Thuốc gây mê y tế không độc và buồng dò vật chất tối trong vật lý hạt'],['Ion-propulsion fuel powering satellites & deep-space probes','High-intensity cinema projector lamps & automotive headlights','Noble-gas surgical anesthetic & dark-matter physics detectors'],'Khí hiếm nặng gấp 4,5 lần không khí; là khí hiếm đầu tiên được chứng minh tạo thành hợp chất hóa học bền (năm 1962).','4.5× denser than air; became the first noble gas ever coaxed into forming a stable chemical compound (1962).'],
  55: [['Đồng hồ nguyên tử Xesi-133 định nghĩa chuẩn đơn vị giây (s) toàn cầu','Dung dịch khoan dầu khí xesi format mật độ siêu cao cho giếng sâu','Tế bào quang điện, đèn nhìn đêm hồng ngoại và xúc tác hữu cơ'],['Caesium-133 atomic clocks defining the SI second globally','Ultra-dense caesium formate brines for deep oil drilling','Photoelectric cells, infrared night-vision & catalysts'],'Kim loại màu vàng nhạt nóng chảy chỉ ở 28,5°C, có bán kính nguyên tử lớn hàng đầu và phản ứng nổ cực mạnh với nước lạnh.','Pale-golden metal melting at 28.5°C, reacting explosively even with cold water or ice.'],
  56: [['Thuốc cản quang Bari sunfat (BaSO₄) khi chụp X-quang dạ dày, ruột','Tạo sắc xanh lục sáng rực trong pháo hoa (Ba(NO₃)₂)','Dung dịch khoan dầu khí (quặng barit) và hút khí dư trong đèn chân không'],['Barium sulfate (BaSO₄) contrast meals for GI tract X-rays','Vivid emerald-green fireworks colorant (Ba(NO₃)₂)','Barite oil-drilling muds & vacuum-tube oxygen getters'],'Hợp chất hòa tan của bari rất độc, nhưng BaSO₄ lại hoàn toàn không tan trong nước và axit dạ dày nên tuyệt đối an toàn khi uống chụp X-quang.','Soluble barium salts are toxic, yet BaSO₄ is completely insoluble in stomach acid, making it safe for X-ray imaging.'],
  57: [['Thấu kính máy ảnh, kính thiên văn có chiết suất cao và độ tán sắc thấp','Cực âm pin sạc NiMH trên hàng triệu xe ô tô hybrid','Chất xúc tác cracking dầu mỏ sản xuất xăng hiệu suất cao'],['High-index, low-dispersion camera & telescope lenses','NiMH rechargeable battery anodes in hybrid vehicles','Fluid catalytic cracking (FCC) catalysts in oil refineries'],'Nguyên tố mở đầu họ Lantan; kim loại mềm dẻo có thể cắt bằng dao và oxi hóa nhanh ngoài không khí ẩm.','Opening member of the lanthanides; ductile enough to cut with a knife and oxidizes quickly in moist air.'],
  58: [['Đá đánh lửa bật lửa (hợp kim ferrocerium) phát tia lửa cực mạnh','Bột oxit xeri (CeO₂) đánh bóng siêu mịn gương quang học và màn hình kính','Bộ chuyển đổi xúc tác khí thải ô tô và thành lò nướng tự làm sạch'],['Ferrocerium lighter flints producing showers of bright sparks','Cerium oxide (CeO₂) precision polishing of lenses & screens','Automotive catalytic converters & self-cleaning oven walls'],'Nguyên tố đất hiếm dồi dào nhất trong vỏ Trái Đất — thậm chí còn phổ biến hơn cả đồng và chì.','The most abundant rare-earth element in Earth’s crust—actually more plentiful than copper or lead.'],
  59: [['Kính bảo hộ thợ thổi thủy tinh và thợ hàn lọc trọn ánh sáng vàng chói','Hợp kim magie cường độ cao cho động cơ phản lực máy bay','Tạo sắc vàng chanh cho gốm sứ và pha vào nam châm neodim'],['Didymium glassblower & welder goggles blocking yellow glare','High-strength magnesium alloys for aircraft engines','Vibrant yellow ceramic glazes & high-power magnets'],'Tạo ra các muối có màu xanh lục vàng đặc trưng; cùng với neodim tạo nên thủy tinh didymium lọc quang phổ xuất sắc.','Forms bright yellow-green salts and combines with neodymium to make precision spectral-filtering glass.'],
  60: [['Nam châm vĩnh cửu mạnh nhất thế giới (Nd₂Fe₁₄B) trong xe điện, tuabin gió','Loa tai nghe, micro, ổ cứng và động cơ không chổi than nhỏ gọn','Laser rắn Nd:YAG công nghiệp và thủy tinh đổi màu theo nguồn sáng'],['World’s strongest permanent magnets (NdFeB) in EVs & wind turbines','Headphone drivers, microphones, hard drives & compact motors','Industrial Nd:YAG solid-state lasers & color-shifting glass'],'Một viên nam châm neodim nhỏ vài gam có thể nâng vật nặng gấp hơn 1000 lần trọng lượng chính nó.','A small neodymium magnet can lift more than 1,000 times its own weight.'],
  61: [['Pin hạt nhân beta-voltaic siêu nhỏ tuổi thọ nhiều năm cho thiết bị vũ trụ','Cảm biến đo độ dày lá kim loại và giấy chính xác trong công nghiệp','Sơn dạ quang đặc chủng trên đồng hồ và bảng điều khiển chuyên dụng'],['Miniature long-life betavoltaic nuclear batteries for space','Precision industrial thickness gauges for metal & paper sheets','Specialized self-luminous instrument dial coatings'],'Nguyên tố đất hiếm duy nhất hoàn toàn phóng xạ trong họ Lantan, gần như không tồn tại trong tự nhiên trên Trái Đất.','The only completely radioactive lanthanide, occurring only in infinitesimal trace amounts in nature.'],
  62: [['Nam châm vĩnh cửu SmCo chịu nhiệt trên 300°C cho vệ tinh và cảm biến','Thanh hấp thụ neutron an toàn trong lò phản ứng hạt nhân','Đồng vị Sm-153 giảm đau xương trong y học hạt nhân ung thư'],['High-temperature SmCo magnets (>300°C) for aerospace & sensors','Neutron-absorbing control materials in nuclear reactors','Radioisotope Sm-153 for targeted bone-pain cancer therapy'],'Nam châm samari-coban chống khử từ và chống ăn mòn ở nhiệt độ cao vượt trội hơn nam châm neodim.','Samarium-cobalt magnets resist demagnetization and corrosion at extreme temperatures where NdFeB fails.'],
  63: [['Bột huỳnh quang đỏ/xanh lam chống tiền giả trên tờ tiền Euro','Bột phát quang màn hình, đèn huỳnh quang tiết kiệm điện và LED','Nghiên cứu vật liệu hấp thụ neutron và quang học lượng tử'],['Anti-counterfeiting red/blue fluorescent ink in Euro banknotes','Red and blue phosphors for displays & warm white LEDs','Neutron-control alloys & quantum optical memory research'],'Kim loại đất hiếm phản ứng hóa học mạnh nhất, mềm gần như chì và bốc cháy trong không khí khi nung nhẹ.','Most chemically reactive rare-earth metal; nearly as soft as lead and glows vibrantly in phosphor compounds.'],
  64: [['Chất tương phản tiêm tĩnh mạch tăng độ nét ảnh chụp cộng hưởng từ MRI','Hệ thống làm lạnh từ trường hiệu suất cao thân thiện môi trường','Hấp thụ neutron nhiệt cực mạnh trong hệ thống an toàn lò phản ứng'],['Intravenous contrast agents sharpening clinical MRI scans','Eco-friendly magnetic refrigeration prototypes','Exceptional thermal neutron absorber for nuclear reactor safety'],'Sở hữu tiết diện hấp thụ neutron nhiệt cao nhất mọi nguyên tố ổn định và tính thuận từ cực mạnh ở nhiệt độ phòng.','Has the highest thermal-neutron capture cross-section of any stable element and strong room-temperature paramagnetism.'],
  65: [['Bột phát quang màu xanh lục tinh khiết trong đèn LED và màn hình','Hợp kim từ giảo Terfenol-D biến đổi hình dạng theo từ trường cho loa siêu âm','Ổn định tinh thể tế bào nhiên liệu oxit rắn nhiệt độ cao'],['Pure emerald-green phosphors for displays & tri-band lamps','Magnetostrictive Terfenol-D actuators & sonar transducers','Stabilizer in high-temperature solid oxide fuel cells'],'Hợp chất terbi phát huỳnh quang màu xanh lục cực sáng dưới tia cực tím — từng được dùng làm mực bảo mật tiền giấy.','Terbium compounds fluoresce vivid bright green under ultraviolet light, also used in security inks.'],
  66: [['Pha vào nam châm NdFeB giúp động cơ xe điện chịu nhiệt không mất từ tính','Đèn chiếu sáng thương mại cường độ cao và thanh điều khiển lò phản ứng','Vật liệu ghi dữ liệu quang từ mật độ cao'],['Added to EV NdFeB magnets to prevent high-heat demagnetization','High-intensity commercial lamps & reactor control rods','Magneto-optical data storage & magnetostrictive alloys'],'Tên gọi bắt nguồn từ tiếng Hy Lạp "dysprositos" (khó tiếp cận); có độ cảm từ cực cao ở nhiệt độ thấp.','Named from Greek "dysprositos" (hard to get); exhibits exceptionally high magnetic susceptibility at low temperatures.'],
  67: [['Đầu cực tập trung từ trường siêu mạnh trong nam châm nghiên cứu','Laser Ho:YAG tán sỏi thận và phẫu thuật mô mềm ít xâm lấn','Hiệu chuẩn quang phổ kế quang học nhờ các vạch hấp thụ siêu sắc nét'],['Magnetic flux concentrators for ultra-high-field magnets','Ho:YAG medical lasers for kidney stones & precise surgery','Optical spectrophotometer wavelength calibration standards'],'Nắm giữ kỷ lục mômen từ tự nhiên lớn nhất trong toàn bộ 118 nguyên tố hóa học.','Holds the record for the strongest natural magnetic moment of any element in the periodic table.'],
  68: [['Bộ khuếch đại sợi quang EDFA truyền tín hiệu Internet xuyên đại dương','Laser Er:YAG tái tạo da thẩm mỹ và điều trị nha khoa không đau','Tạo sắc hồng dịu bền màu cho kính mát và gốm sứ cao cấp'],['Erbium-doped fiber amplifiers (EDFA) powering global Internet cables','Er:YAG lasers for gentle dermatology & dental treatments','Soft pink tinting for sunglasses & fine decorative glass'],'Ion Er³⁺ khuếch đại trực tiếp tín hiệu ánh sáng bước sóng 1550 nm trong cáp quang mà không cần đổi sang tín hiệu điện.','Er³⁺ ions directly amplify 1550 nm optical signals inside fiber cables without electrical conversion.'],
  69: [['Nguồn phát tia X di động nhỏ gọn không cần điện lưới cho y tế dã chiến','Laser Tm:YAG phẫu thuật cắt mô chính xác và cảm biến khí quyển LIDAR','Chất phát quang xanh lam chống làm giả tiền giấy'],['Portable battery-free X-ray sources for field medicine','Tm:YAG surgical lasers & atmospheric LIDAR sensors','Blue UV-fluorescent anti-counterfeiting phosphors'],'Nguyên tố đất hiếm ổn định hiếm nhất trong tự nhiên nhưng lại rất hữu dụng nhờ bức xạ đơn sắc chuẩn xác.','Least abundant stable rare-earth element in nature, prized for crisp monochromatic X-ray and laser emission.'],
  70: [['Đồng hồ nguyên tử mạng quang học ytecbi sai số <1 giây trong hàng tỷ năm','Laser sợi quang công suất hàng kilowatt cắt hàn công nghiệp','Cảm biến đo ứng suất địa chấn và cải thiện độ bền thép không gỉ'],['Ytterbium optical lattice clocks accurate to billions of years','High-power industrial fiber lasers for precision cutting/welding','Seismic stress gauges & grain refiner in stainless steels'],'Độ dẫn điện thay đổi mạnh dưới áp suất cao, giúp chế tạo cảm biến đo sóng xung kích chính xác.','Electrical resistance shifts sharply under high pressure, enabling precision shockwave and stress sensors.'],
  71: [['Tinh thể nhấp nháy LSO/LYSO bên trong máy chụp cắt lớp phát positron (PET)','Chất xúc tác cracking dầu mỏ và phản ứng trùng hợp chuyên biệt','Định tuổi thiên thạch và đá cổ địa chất bằng đồng vị Lu-176'],['LSO/LYSO scintillator crystals inside medical PET scanners','Specialized petroleum cracking & polymerization catalysts','Radiometric dating of ancient rocks & meteorites (Lu-176)'],'Nặng nhất, cứng nhất và có nhiệt độ nóng chảy cao nhất trong toàn bộ 15 nguyên tố họ Lantan.','Densest, hardest, and highest-melting member of all 15 lanthanide elements.'],
  72: [['Lớp điện môi cổng high-k (HfO₂) trong hầu hết CPU/chip hiện đại (<45nm)','Thanh điều khiển an toàn lò phản ứng hạt nhân trên tàu ngầm nguyên tử','Đầu điện cực máy cắt plasma và siêu hợp kim động cơ tên lửa'],['High-k gate dielectric (HfO₂) inside modern microchips','Nuclear control rods aboard naval reactors & submarines','Plasma-cutter electrodes & rocket thruster alloys'],'Giống hệt zirconi về hóa tính nhưng lại trái ngược hoàn toàn về hạt nhân: hafini hấp thụ neutron cực kỳ mạnh.','Chemically almost identical to zirconium yet nuclearly opposite—hafnium absorbs neutrons aggressively.'],
  73: [['Tụ điện tantan siêu nhỏ, độ bền cao trong điện thoại, laptop và ô tô','Dụng cụ cấy ghép phẫu thuật, lưới sọ não hoàn toàn trơ với dịch cơ thể','Thiết bị trao đổi nhiệt và bình phản ứng chứa axit đậm đặc'],['Miniature high-reliability capacitors in smartphones & vehicles','Completely bio-inert surgical implants & cranial plates','Chemical-plant vessels handling concentrated boiling acids'],'Hầu như miễn nhiễm với mọi axit dưới 150°C (kể cả nước cường toan) và có nhiệt độ nóng chảy trên 3000°C.','Virtually immune to chemical attack by acids below 150°C (including aqua regia) and melts above 3000°C.'],
  74: [['Dây tóc bóng đèn, điện cực hàn TIG và ống phát tia X chịu nhiệt cực cao','Cacbua vonfram (WC) siêu cứng làm mũi khoan, dao tiện và nhẫn chống xước','Đối trọng cân bằng cánh máy bay, xe đua F1 và tấm chắn bức xạ'],['Light-bulb filaments, TIG welding electrodes & X-ray targets','Ultra-hard tungsten carbide (WC) drills, cutting tools & rings','High-density counterweights for aircraft, F1 cars & shielding'],'Giữ kỷ lục nhiệt độ nóng chảy cao nhất trong tất cả các kim loại nguyên chất (3422°C) và tỷ trọng nặng ngang vàng.','Holds the highest melting point of all pure metals (3422°C) with a density nearly matching solid gold.'],
  75: [['Siêu hợp kim niken-reni làm cánh tuabin động cơ phản lực thương mại & quân sự','Chất xúc tác cải tiến xăng chỉ số octan cao không chì (Pt-Re)','Cặp nhiệt điện đo nhiệt độ siêu cao tới 2200°C'],['Nickel-rhenium superalloys for jet-engine turbine blades','Pt-Re catalysts producing high-octane unleaded gasoline','Extreme-temperature thermocouples measuring up to 2200°C'],'Một trong những nguyên tố hiếm nhất vỏ Trái Đất và là nguyên tố ổn định cuối cùng được phát hiện (1925).','Among the rarest elements in Earth’s crust and the final stable element to be discovered (1925).'],
  76: [['Hợp kim osimi-iridi siêu bền làm ngòi bút máy cao cấp và chốt kim đồng hồ','Tiếp điểm điện chịu hồ quang và kim máy hát đĩa than cổ điển','Chất nhuộm OsO₄ trong kính hiển vi điện tử soi mẫu sinh học'],['Ultra-durable osmium-iridium fountain pen nibs & instrument pivots','Arc-resistant electrical contacts & precision bearings','OsO₄ biological tissue stain for electron microscopy'],'Nắm giữ kỷ lục nguyên tố tự nhiên đặc nhất Trái Đất (22,59 g/cm³ — nặng hơn chì gần gấp đôi).','Densest naturally occurring element on Earth (22.59 g/cm³)—nearly twice as dense as lead.'],
  77: [['Đầu điện cực bugi đánh lửa iridi siêu bền cho ô tô, xe máy','Nồi nấu tinh thể đơn nhiệt độ cao nuôi ngọc bích cho màn hình & LED','Hợp kim Pt-Ir chế tạo thanh chuẩn mét và kilôgam lịch sử quốc tế'],['Long-life iridium spark plugs in modern car engines','High-temperature crucibles for growing sapphire LED crystals','Pt-Ir alloys for historical international meter & kilogram bars'],'Kim loại chống ăn mòn mạnh nhất từng biết; lớp trầm tích giàu iridi trên toàn cầu là dấu vết thiên thạch tuyệt chủng khủng long.','Most corrosion-resistant metal known; a global iridium-rich clay layer marks the dinosaur-killing asteroid impact.'],
  78: [['Bộ chuyển đổi xúc tác ô tô và pin nhiên liệu hydro sạch (PEMFC)','Thuốc hóa trị gốc platin (cisplatin, carboplatin) điều trị nhiều bệnh ung thư','Trang sức bạch kim cao cấp, cảm biến nhiệt điện trở chuẩn Pt100'],['Automotive catalytic converters & hydrogen fuel cells (PEMFC)','Life-saving platinum chemotherapy drugs (cisplatin, carboplatin)','Luxury platinum jewelry & precision Pt100 temperature sensors'],'Kim loại quý nặng, bền trơ tuyệt đối, không bị xỉn màu theo thời gian và có hoạt tính xúc tác hóa học vượt trội.','Dense, noble precious metal that never tarnishes and serves as an unrivaled industrial and fuel-cell catalyst.'],
  79: [['Chân tiếp xúc vi mạch, dây nối siêu mảnh trong điện thoại và máy tính','Trang sức, dự trữ tài chính quốc gia và lá vàng dát mỏng siêu mịn','Lớp mạ phản xạ hồng ngoại trên mũ phi hành gia và gương kính viễn vọng JWST'],['Corrosion-proof microchip contacts & bonding wires in electronics','Fine jewelry, central-bank reserves & edible/artistic gold leaf','Infrared-reflective coatings on astronaut visors & JWST mirrors'],'1 gam vàng có thể dát mỏng thành tấm rộng tới 1 m² hoặc kéo thành sợi dài hàng km mà không bị đứt hay oxi hóa.','A single gram can be beaten into a 1 m² translucent sheet or drawn into kilometers of wire without tarnishing.'],
  80: [['Đèn huỳnh quang, đèn hơi thủy ngân chiếu sáng và diệt khuẩn UV','Nhiệt kế, áp kế chuẩn khoa học (hiện đang dần thay thế vì lý do môi trường)','Hỗn hống nha khoa và công tắc cảm biến nghiêng chuyên dụng'],['Fluorescent & UV germicidal mercury-vapor lamps','Scientific barometers & thermometers (phasing out for safety)','Traditional dental amalgams & specialized tilt switches'],'Kim loại duy nhất tồn tại ở thể lỏng tại nhiệt độ phòng (-38,83°C đã nóng chảy), có sức căng bề mặt cực lớn tạo giọt tròn lăn.','The only metal liquid at room temperature (melting at -38.83°C) with high surface tension forming rolling beads.'],
  81: [['Đồng vị Tl-201 đánh giá tưới máu cơ tim trong y học hạt nhân','Thấu kính hồng ngoại (KRS-5) và kính chiết suất siêu cao','Nghiên cứu vật liệu siêu dẫn nhiệt độ cao chứa tali'],['Isotope Tl-201 for cardiac stress-test nuclear imaging','Infrared optical lenses (KRS-5) & high-index glass','High-temperature thallium-based superconductor research'],'Mềm như chì, dễ cắt và để lại vạch quang phổ màu xanh lá rực rỡ ("thallos" nghĩa là chồi non xanh), nhưng cực kỳ độc.','Lead-soft metal named for its bright green spectral line ("thallos", green shoot), though extremely toxic.'],
  82: [['Ắc quy axit-chì khởi động ô tô, xe máy và hệ thống lưu điện dự phòng','Tấm chắn tia X tại phòng chụp bệnh viện và tường che bức xạ hạt nhân','Tấm cách âm, đối trọng cân bằng và cáp ngầm chống ăn mòn'],['Lead-acid starter & backup batteries for cars and UPS systems','X-ray shielding aprons & walls in hospitals and nuclear labs','Acoustic soundproofing sheets & dense marine ballast'],'Rất đặc, mềm dẻo dễ uốn và hấp thụ bức xạ ion hóa xuất sắc; hiện đã loại bỏ khỏi xăng và sơn do độc tính thần kinh.','Dense, malleable, and superb at blocking ionizing radiation; phased out of fuels and paints due to neurotoxicity.'],
  83: [['Thuốc giảm đau dạ dày bismuth subsalicylate (Pepto-Bismol)','Hợp kim hàn và đạn không chì thân thiện môi trường thay thế chì độc','Tinh thể bitmut bậc thang óng ánh bảy sắc cầu vồng trong mỹ thuật & giáo dục'],['Stomach-relief medicine bismuth subsalicylate (Pepto-Bismol)','Non-toxic lead-free solders, fishing sinkers & plumbing alloys','Iridescent rainbow hopper crystals for display & education'],'Kim loại nặng ít độc nhất, sở hữu tính nghịch từ mạnh nhất (có thể đẩy lơ lửng nam châm) và giãn nở nhẹ khi đông đặc.','Least toxic heavy metal, strongest natural diamagnet (can levitate magnets), and expands slightly upon freezing.'],
  84: [['Bàn chải khử tĩnh điện công nghiệp (lượng siêu nhỏ được niêm phong an toàn)','Nguồn nhiệt đồng vị nhẹ trên các tàu đổ bộ Mặt Trăng Lunokhod cổ điển','Nguồn phát hạt alpha tinh khiết trong nghiên cứu vật lý hạt nhân'],['Sealed industrial anti-static brushes for film & precision optics','Lightweight radioisotope heaters on historic Lunokhod rovers','Pure alpha-particle sources in nuclear physics research'],'Phóng xạ alpha dữ dội đến mức một viên poloni tự tỏa nhiệt lên tới 500°C và làm không khí quanh nó phát sáng xanh lam.','So intensely alpha-radioactive that a small capsule self-heats to ~500°C and ionizes surrounding air with a blue glow.'],
  85: [['Nghiên cứu đồng vị At-211 trong xạ trị alpha nhắm trúng đích tế bào ung thư','Thí nghiệm hóa học hạt nhân nghiên cứu tính chất nguyên tố siêu nặng'],['Clinical research on At-211 targeted alpha cancer radiotherapy','Nuclear chemistry studies of heavy relativistic halogens'],'Nguyên tố tự nhiên khan hiếm nhất Trái Đất — tổng lượng tồn tại cùng lúc trong toàn bộ vỏ Trái Đất chỉ khoảng vài chục gam.','Earth’s rarest natural element—estimated at only a few dozen grams across the entire crust at any given instant.'],
  86: [['Đo nồng độ khí radon để cảnh báo an toàn không khí trong tầng hầm, nhà ở','Theo dõi biến động đứt gãy địa chất và dự báo hoạt động thủy văn ngầm'],['Indoor radon monitoring for basement & home air-quality safety','Geochemical tracer for groundwater movement & fault activity'],'Khí hiếm phóng xạ không màu không mùi, nặng hơn không khí gần 8 lần nên thường tích tụ ở các tầng thấp nếu kém thông gió.','Colorless, odorless radioactive noble gas ~8× denser than air, tending to accumulate in poorly ventilated basements.'],
  87: [['Nghiên cứu cấu trúc quang phổ nguyên tử trong bẫy magneto-quang học','Kiểm chứng các định luật vật lý hạt cơ bản (vi phạm tính chẵn lẻ)'],['Laser-trapped atomic spectroscopy research','Precision tests of fundamental electroweak physics'],'Cực kỳ hiếm và phóng xạ mạnh với chu kì bán rã tối đa chỉ 22 phút — chưa từng gom đủ để nhìn thấy bằng mắt thường.','Exceedingly rare and short-lived (max half-life 22 minutes)—never accumulated in visible macroscopic amounts.'],
  88: [['Đồng vị Ra-223 (Xofigo) điều trị nhắm đích ung thư tuyến tiền liệt di căn xương','Nghiên cứu nguồn phát neutron chuẩn trong phòng thí nghiệm hạt nhân'],['Isotope Ra-223 (Xofigo) treating bone-metastatic prostate cancer','Historical neutron sources & radiochemistry benchmarks'],'Kim loại kiềm thổ phóng xạ phát sáng xanh lam mờ trong bóng tối; từng được dùng sơn kim đồng hồ dạ quang đầu thế kỷ 20.','Radioactive alkaline earth metal glowing faintly blue in the dark; famously used on early-20th-century watch dials.'],
  89: [['Đồng vị Ac-225 đang rất triển vọng trong liệu pháp alpha nhắm đích trị ung thư','Nguồn tạo neutron và nghiên cứu nguồn nhiệt đồng vị phóng xạ'],['Promising Ac-225 isotope for targeted alpha cancer therapy','Neutron sources & radioisotope thermoelectric research'],'Nguyên tố mở đầu họ Actini, phóng xạ mạnh gấp ~150 lần radi khiến không khí xung quanh nó phát ánh sáng xanh lam rõ rệt.','Opening actinide; ~150× more radioactive than radium, illuminating surrounding air with an eerie blue glow.'],
  90: [['Nhiên liệu tiềm năng cho lò phản ứng muối nóng chảy thori thế hệ mới','Thấu kính quang học đặc chủng, điện cực hàn TIG và lưới đèn măng-sông cổ điển','Hợp kim magie chịu nhiệt cao cho động cơ hàng không'],['Promising fuel for next-generation molten-salt nuclear reactors','TIG welding electrodes & classic gas-lantern mantles','High-temperature aerospace magnesium-thorium alloys'],'Phổ biến gấp 3–4 lần urani trong vỏ Trái Đất và tạo ra lượng chất thải phóng xạ sống lâu ít hơn đáng kể khi khai thác năng lượng.','3–4× more abundant than uranium in Earth’s crust with potential for significantly less long-lived nuclear waste.'],
  91: [['Định tuổi trầm tích đáy đại dương và cổ khí hậu học (tỷ lệ Pa-231 / Th-230)','Nghiên cứu khoa học cơ bản về cấu trúc phân lớp 5f trong hóa học hạt nhân'],['Paleoceanography & marine sediment dating (Pa-231/Th-230)','Basic nuclear chemistry studies of 5f-orbital bonding'],'Cực kỳ hiếm, phóng xạ mạnh và độc tính cao nên hầu như không có ứng dụng thương mại ngoài nghiên cứu khoa học.','Extremely scarce, intensely radioactive, and highly toxic with virtually no commercial uses outside research.'],
  92: [['Nhiên liệu phân hạch (U-235) phát điện tại hàng trăm nhà máy điện hạt nhân','Urani nghèo siêu đặc làm đối trọng máy bay và tấm chắn phóng xạ','Định tuổi đá địa chất và tuổi Trái Đất (4,5 tỷ năm) bằng phân rã U-Pb'],['Fissile U-235 fuel powering nuclear electricity plants worldwide','Ultra-dense depleted uranium aircraft ballast & radiation shields','Uranium-lead (U-Pb) radiometric dating of Earth’s oldest rocks'],'1 kg urani làm giàu có thể giải phóng nguồn năng lượng nhiệt tương đương hàng nghìn tấn than đá.','1 kg of fissile uranium releases as much thermal energy as thousands of metric tons of coal.'],
  93: [['Bia chiếu xạ neutron để sản xuất Plutoni-238 cấp nguồn cho tàu thám hiểm vũ trụ','Cảm biến phát hiện neutron năng lượng cao trong vật lý hạt nhân'],['Target material irradiated to make Pu-238 for deep-space probes','High-energy neutron detectors in nuclear physics'],'Nguyên tố siêu urani đầu tiên từng được tổng hợp nhân tạo (1940), có tính chất hóa học rất linh hoạt với 5 trạng thái oxi hóa.','First synthetic transuranium element ever created (1940), displaying five accessible oxidation states in solution.'],
  94: [['Nguồn nhiệt đồng vị Pu-238 (RTG) cấp điện hàng chục năm cho tàu Voyager, Curiosity, Perseverance','Nhiên liệu hạt nhân hỗn hợp MOX phát điện tại nhà máy điện nguyên tử'],['Pu-238 radioisotope generators (RTGs) powering Voyager & Mars rovers','MOX mixed-oxide nuclear fuel for electricity generation'],'Có tới 6 dạng thù hình tinh thể phức tạp và đồng vị Pu-238 tự nóng đỏ hồng lên nhờ năng lượng phân rã alpha ổn định.','Exhibits six complex solid crystal phases, while Pu-238 glows dull red from steady alpha-decay heat.'],
  95: [['Đồng vị Am-241 trong hầu hết đầu báo khói ion hóa gia đình','Thiết bị đo mật độ vật liệu, độ dày kính và phân tích huỳnh quang tia X'],['Am-241 ionization source inside everyday household smoke detectors','Industrial density/thickness gauges & X-ray fluorescence probes'],'Lượng Am-241 trong mỗi đầu báo khói cực kỳ nhỏ (chưa đến 1 microgam) và được bọc kín an toàn để phát hiện khói sớm.','Each household smoke detector contains less than a microgram of safely sealed Am-241 to sense smoke particles early.'],
  96: [['Nguồn phát hạt alpha trên xe tự hành Curiosity & Perseverance phân tích đá Sao Hỏa','Nguồn năng lượng đồng vị mật độ nhiệt cao cho thiết bị không gian'],['Alpha-particle X-ray spectrometers on Mars rovers analyzing rocks','Compact high-power radioisotope heat sources for space missions'],'Kim loại nặng ánh bạc sáng, tự phát sáng đỏ nhạt trong bóng tối do năng lượng phân rã phóng xạ rất lớn.','Silvery heavy actinide whose intense radioactivity causes it to glow dimly red in darkness.'],
  97: [['Bia mục tiêu quan trọng để tổng hợp các nguyên tố siêu nặng (như Tennessine Z=117)','Nghiên cứu hóa học nguyên tố siêu nặng trong phòng thí nghiệm hạt nhân'],['Crucial target material for forging superheavy elements (like Tennessine)','Fundamental heavy-actinide chemistry research'],'Chỉ được sản xuất với sản lượng tính bằng miligam trong các lò phản ứng hạt nhân nghiên cứu chuyên biệt.','Produced only in milligram quantities inside specialized high-flux research nuclear reactors.'],
  98: [['Nguồn phát neutron khởi động lò phản ứng hạt nhân mới','Máy phân tích quặng mỏ, phát hiện vết nứt cánh máy bay và dò dầu khí','Xạ trị neutron đặc hiệu điều trị một số khối u kháng tia X'],['Neutron startup sources for nuclear power reactors','Coal/ore analyzers, aircraft stress inspection & oil well logging','Specialized neutron brachytherapy for X-ray-resistant tumors'],'1 microgam Californium-252 phát ra tới ~170 triệu neutron mỗi phút — nguồn neutron di động mạnh bậc nhất.','A single microgram of Cf-252 emits ~170 million neutrons per minute—an extraordinary compact neutron source.'],
  99: [['Bia mục tiêu tạo nguyên tố nặng hơn (như Mendelevi Z=101)','Nghiên cứu hóa học phóng xạ và hiệu ứng tương đối tính của lớp vỏ 5f'],['Target material used to synthesize heavier elements like mendelevium','Radiochemistry & relativistic 5f-electron research'],'Được phát hiện bất ngờ năm 1952 trong tro bụi vụ thử nhiệt hạch Ivy Mike và chỉ tồn tại lượng siêu nhỏ trong phòng thí nghiệm.','Unexpectedly discovered in 1952 fallout from the Ivy Mike test; exists only in microscopic lab samples.'],
  100: [['Nghiên cứu vật lý hạt nhân về giới hạn bắt giữ neutron trong lò phản ứng','Thí nghiệm đo tính chất hóa học trên từng vài nguyên tử riêng lẻ'],['Nuclear physics research on neutron-capture limits','Single-atom-scale radiochemistry experiments'],'Nguyên tố nặng nhất có thể tạo bằng cách bắn phá neutron vào nguyên tố nhẹ hơn — muốn tạo từ Z=101 trở đi phải dùng máy gia tốc ion nặng.','Heaviest element reachable by neutron bombardment; elements Z≥101 require heavy-ion particle accelerators.'],
  101: [['Nghiên cứu vật lý hạt nhân và cơ chế phân hạch tự phát của hạt nhân nặng','Kiểm chứng lý thuyết tuần hoàn hóa học ở cuối dãy Actini'],['Studies of heavy-nucleus spontaneous fission','Testing periodic-law predictions near the end of the actinides'],'Đặt tên vinh danh Dmitri Mendeleev; được tổng hợp lần đầu năm 1955 từng nguyên tử một (chỉ 17 nguyên tử trong thí nghiệm đầu tiên!).','Honors Dmitri Mendeleev; first synthesized atom-by-atom in 1955—only 17 atoms were produced in the discovery run!'],
  102: [['Thí nghiệm hóa học siêu vi mô khám phá trạng thái oxi hóa +2 bền bất thường','Nghiên cứu cấu trúc hạt nhân gần lớp vỏ đóng Z=102'],['Micro-scale chemistry probing its unusually stable +2 oxidation state','Nuclear shell-structure experiments near Z=102'],'Khác với đa số họ Actini thích mức +3, Nobeli lại bền nhất ở số oxi hóa +2 do cấu hình phân lớp 5f¹⁴ đã lấp đầy hoàn toàn.','Unlike most actinides preferring +3, nobelium favors +2 due to its completely filled 5f¹⁴ subshell.'],
  103: [['Nghiên cứu vị trí ranh giới giữa phân lớp f và d trong bảng tuần hoàn hiện đại','Đo năng lượng ion hóa cực thấp bằng kỹ thuật từng nguyên tử trong máy gia tốc'],['Research clarifying the f-block / d-block boundary of the periodic table','Single-atom ionization-potential measurements in accelerators'],'Nguyên tố khép lại họ Actini; hiệu ứng tương đối tính đẩy electron cuối cùng lên phân lớp 7p¹ thay vì 6d¹ như dự đoán cổ điển.','Closes the actinide series; relativistic effects unexpectedly place its outermost electron into 7p¹ rather than 6d¹.'],
  104: [['Nghiên cứu cơ bản về hóa học nguyên tố siêu nặng nhóm 4 (so sánh với Zr, Hf)','Khảo sát độ bền hạt nhân hướng tới "đảo ổn định"'],['Fundamental group-4 superheavy chemistry (comparing with Zr and Hf)','Nuclear stability research approaching the "island of stability"'],'Nguyên tố siêu nặng chuyển tiếp đầu tiên (transactinide), chỉ tổng hợp được lượng cực nhỏ và phân rã trong khoảng vài phút đến hơn một giờ.','First transactinide superheavy element; synthesized in tiny amounts with half-lives ranging from seconds to ~1 hour.'],
  105: [['Nghiên cứu phản ứng hóa học pha khí của nguyên tố siêu nặng nhóm 5','Kiểm chứng ảnh hưởng của hiệu ứng tương đối tính lên liên kết hóa học'],['Gas-phase superheavy chemistry in group 5','Testing relativistic effects on chemical bonding'],'Đồng vị bền nhất Db-268 có chu kì bán rã khoảng 28 giờ — khá dài so với mặt bằng các nguyên tố siêu nặng.','Its longest-lived isotope Db-268 lasts ~28 hours—remarkably long among superheavy elements.'],
  106: [['Thí nghiệm tổng hợp hợp chất cacbonyl siêu nặng Sg(CO)₆ nổi tiếng','Kiểm nghiệm tính tuần hoàn của nhóm 6 cùng Cr, Mo và W'],['Landmark synthesis of superheavy carbonyl Sg(CO)₆','Validating group-6 periodic trends alongside Cr, Mo, and W'],'Là nguyên tố đầu tiên được đặt theo tên một nhà khoa học còn đang sống vào thời điểm công bố (Glenn T. Seaborg).','First element named after a living scientist at the time of its naming (Nobel laureate Glenn T. Seaborg).'],
  107: [['Nghiên cứu vật lý hạt nhân và hóa học siêu nhanh nhóm 7 (so sánh với Reni)','Khảo sát rào cản phân hạch của hạt nhân có số proton Z=107'],['Ultrafast group-7 chemistry experiments (comparing with rhenium)','Fission-barrier studies of Z=107 superheavy nuclei'],'Mọi đồng vị đã biết đều rất ngắn ngủi (chu kì bán rã lớn nhất khoảng 1 phút), chỉ phục vụ nghiên cứu khoa học cơ bản.','All known isotopes are short-lived (up to ~1 minute), studied strictly in accelerator physics labs.'],
  108: [['Tổng hợp thành công oxit dễ bay hơi HsO₄ xác nhận vị trí nhóm 8 giống Osimi','Nghiên cứu cấu trúc hạt nhân biến dạng bền tại Z=108, N=162'],['Synthesis of volatile HsO₄ confirming osmium-like group-8 chemistry','Studies of deformed nuclear shell stability at Z=108, N=162'],'Các tính toán lý thuyết dự đoán nếu tạo thành khối rắn, Hassi có thể đặc tới ~41 g/cm³ — gần gấp đôi osimi.','Theoretical models predict bulk hassium would have an astonishing density around ~41 g/cm³—nearly twice osmium.'],
  109: [['Nghiên cứu tổng hợp hạt nhân bằng phản ứng nhiệt hạch lạnh trong máy gia tốc','Khảo sát chuỗi phân rã alpha của các hạt nhân siêu nặng lẻ-Z'],['Cold-fusion accelerator synthesis research','Alpha-decay chain studies of odd-Z superheavy nuclei'],'Vinh danh Lise Meitner; các đồng vị của nó phân rã trong vài giây nên tính chất hóa học hiện vẫn chỉ được dự đoán bằng tính toán lượng tử.','Honors Lise Meitner; isotopes decay within seconds, so its chemical properties remain quantum-predicted.'],
  110: [['Nghiên cứu cơ chế tổng hợp hạt nhân siêu nặng và phân rã alpha','Dự đoán hóa học nhóm 10 dưới ảnh hưởng mạnh của hiệu ứng tương đối tính'],['Superheavy fusion mechanism & alpha-decay research','Relativistic quantum predictions for group-10 chemistry'],'Tổng hợp lần đầu tại viện GSI (Darmstadt, Đức) bằng cách bắn chùm ion niken-62 vào bia chì-208.','First forged at GSI (Darmstadt, Germany) by firing nickel-62 ions into a lead-208 target.'],
  111: [['Nghiên cứu vật lý hạt nhân về sự ổn định vỏ proton siêu nặng','Mô phỏng tính chất quang học (dự đoán có màu ánh bạc thay vì vàng như Au)'],['Nuclear physics probes of superheavy shell closure','Relativistic simulations (predicted silvery rather than gold-colored)'],'Nằm ngay dưới đồng, bạc, vàng nhưng hiệu ứng tương đối tính được dự đoán khiến Rơngheni có ánh trắng bạc thay vì màu vàng.','Sits directly below Cu, Ag, and Au, yet relativistic electron shifts are predicted to make it silvery rather than golden.'],
  112: [['Thí nghiệm sắc ký hấp phụ nhiệt độ thấp chứng minh tính cực kỳ dễ bay hơi','Khảo sát hiệu ứng tương đối tính làm kim loại nhóm 12 cư xử gần giống khí hiếm'],['Cryo-adsorption experiments demonstrating extreme volatility','Studying relativistic effects making a group-12 metal act noble-gas-like'],'Các thí nghiệm nguyên tử đơn cho thấy Copernixi dễ bay hơi hơn cả thủy ngân và có thể tồn tại ở thể khí ngay nhiệt độ phòng!','Single-atom experiments confirm copernicium is even more volatile than mercury and may be a gas at room temperature.'],
  113: [['Nghiên cứu vật lý hạt nhân siêu nặng tại viện RIKEN (Nhật Bản)','Thăm dò tính chất hóa học nhóm 13 siêu nặng và hiệu ứng ghép spin-quỹ đạo'],['Superheavy accelerator physics at RIKEN (Japan)','Probing group-13 chemistry under strong spin-orbit coupling'],'Nguyên tố đầu tiên trong lịch sử được khám phá và đặt tên bởi các nhà khoa học châu Á (từ "Nihon" — Nhật Bản).','First element in history discovered and named by scientists in Asia (from "Nihon", Japan).'],
  114: [['Nghiên cứu "đảo ổn định" hạt nhân quanh số thần kỳ Z=114','Thí nghiệm hấp phụ bề mặt vàng kiểm chứng tính trơ tương đối tính bất thường'],['Exploring the predicted nuclear "island of stability" around Z=114','Gold-surface adsorption tests of its surprisingly low reactivity'],'Nằm trong vùng gần "đảo ổn định" lý thuyết; một số thí nghiệm cho thấy nó ít phản ứng hơn chì và khá dễ bay hơi.','Lies near the predicted island of stability; experiments hint it is far less reactive and more volatile than lead.'],
  115: [['Nghiên cứu tổng hợp phản ứng nhiệt hạch nóng (Ca-48 + Am-243)','Khảo sát chuỗi phân rã tạo ra Nihoni (Z=113) và các hạt nhân giàu neutron'],['Hot-fusion synthesis studies (Ca-48 + Am-243)','Decay-chain research producing nihonium (Z=113)'],'Chỉ mới có khoảng vài chục đến hàng trăm nguyên tử từng được tạo ra trong phòng thí nghiệm, tồn tại trong chưa đầy 1 giây.','Only around a hundred atoms have ever been produced in laboratories, decaying in fractions of a second.'],
  116: [['Nghiên cứu mở rộng giới hạn trên của bảng tuần hoàn các nguyên tố','Thí nghiệm kiểm chứng mô hình vỏ hạt nhân siêu nặng'],['Pushing the upper mass frontier of the periodic table','Testing nuclear shell-model predictions for superheavy nuclei'],'Tạo ra bằng cách bắn phá hạt nhân canxi-48 vào bia curi-248; phân rã alpha chỉ sau vài chục mili giây.','Created by bombarding curium-248 with calcium-48 ions, decaying via alpha emission within tens of milliseconds.'],
  117: [['Nghiên cứu lý thuyết và thực nghiệm về giới hạn cuối dãy Halogen','Kiểm tra mức độ thay đổi tính chất phi kim sang á kim/kim loại ở Z=117'],['Experimental & theoretical studies at the bottom of the halogen group','Testing the relativistic shift from nonmetal toward metallic behavior'],'Dù nằm cuối nhóm Halogen (cùng Flo, Clo), hiệu ứng tương đối tính mạnh được dự đoán khiến Tennessine có tính giống kim loại hơn phi kim.','Though placed beneath halogens F and Cl, strong relativistic effects are predicted to give it semi-metallic traits.'],
  118: [['Nghiên cứu biên giới cuối cùng của bảng tuần hoàn hiện đại (Z=118)','Mô phỏng lượng tử về lớp vỏ electron bị biến dạng bởi hiệu ứng tương đối tính'],['Studying the current frontier of the periodic table (Z=118)','Quantum simulations of extreme relativistic electron shells'],'Chỉ mới có 5–6 nguyên tử từng được phát hiện; dù thuộc cột Khí hiếm nhưng dự đoán là chất rắn dễ phân cực ở 25°C thay vì chất khí!','Only ~5–6 atoms have ever been observed; despite sitting in the noble-gas column, it is predicted to be a polarizable solid at 25°C!']
};
